-- BIT-75-02 PREFLIGHT (solo lectura). Conforme = todas las filas 'OK' (las 'VER' son informativas).
SELECT 'tablas base existen (4)' AS chequeo, CASE WHEN to_regclass('public.perfiles') IS NOT NULL AND to_regclass('public.establecimientos') IS NOT NULL AND to_regclass('public.establecimientos_usuarios') IS NOT NULL AND to_regclass('public.bit56_validadores') IS NOT NULL THEN 'OK' ELSE 'FALLA' END AS resultado
UNION ALL SELECT 'BIT-75-01 aplicada (auditoria, 3 funciones, trigger ultimo admin)', CASE WHEN to_regclass('public.usuarios_auditoria') IS NOT NULL AND to_regprocedure('public.bit75_listar_usuarios()') IS NOT NULL AND to_regprocedure('public.bit75_buscar_usuario(text)') IS NOT NULL AND to_regprocedure('public.bit75_proteger_ultimo_admin()') IS NOT NULL AND EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.perfiles'::regclass AND tgname='bit75_proteger_ultimo_admin' AND tgenabled='A') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'trigger BIT-56-03 activo (deja pasar a service_role)', CASE WHEN EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.perfiles'::regclass AND tgname='bit56_proteger_perfiles' AND tgenabled='A') THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'columnas esperadas existen (9)', CASE WHEN (SELECT count(*) FROM pg_attribute a WHERE a.attnum>0 AND NOT a.attisdropped AND ((a.attrelid='public.perfiles'::regclass AND a.attname IN ('id','nombre','rol','activo')) OR (a.attrelid='public.establecimientos'::regclass AND a.attname='id') OR (a.attrelid='public.establecimientos_usuarios'::regclass AND a.attname IN ('perfil_id','establecimiento_id')) OR (a.attrelid='public.bit56_validadores'::regclass AND a.attname IN ('perfil_id','establecimiento_id')))) = 9 THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'service_role existe con BYPASSRLS', CASE WHEN EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role' AND rolbypassrls) THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'service_role SIN privilegios previos sobre las 4 tablas (esperado)', CASE WHEN NOT (has_any_column_privilege('service_role','public.perfiles','SELECT,INSERT,UPDATE') OR has_table_privilege('service_role','public.perfiles','DELETE') OR has_any_column_privilege('service_role','public.establecimientos','SELECT,INSERT,UPDATE') OR has_table_privilege('service_role','public.establecimientos','DELETE') OR has_any_column_privilege('service_role','public.establecimientos_usuarios','SELECT,INSERT,UPDATE') OR has_table_privilege('service_role','public.establecimientos_usuarios','DELETE') OR has_any_column_privilege('service_role','public.bit56_validadores','SELECT,INSERT,UPDATE') OR has_table_privilege('service_role','public.bit56_validadores','DELETE')) THEN 'OK' ELSE 'FALLA (deriva: ya hay privilegios)' END
UNION ALL SELECT 'RLS activo en las 5 tablas', CASE WHEN (SELECT count(*) FROM pg_class WHERE oid IN ('public.perfiles'::regclass,'public.establecimientos'::regclass,'public.establecimientos_usuarios'::regclass,'public.bit56_validadores'::regclass,'public.usuarios_auditoria'::regclass) AND relrowsecurity) = 5 THEN 'OK' ELSE 'FALLA' END
UNION ALL SELECT 'huella privilegios anon/authenticated = BASE (39 privilegios, md5 7b69a42e062cb95d3fd63964c089d343)', CASE WHEN (SELECT md5(coalesce(string_agg(x, ';' ORDER BY x),'')) FROM (SELECT c.relname::text||'|'||a.grantee::regrole::text||'|'||a.privilege_type AS x FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid IN ('public.perfiles'::regclass,'public.establecimientos'::regclass,'public.establecimientos_usuarios'::regclass,'public.bit56_validadores'::regclass,'public.usuarios_auditoria'::regclass) AND a.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated')) UNION ALL SELECT c.relname::text||'.'||att.attname::text||'|'||a.grantee::regrole::text||'|'||a.privilege_type FROM pg_attribute att JOIN pg_class c ON c.oid=att.attrelid CROSS JOIN LATERAL aclexplode(att.attacl) a WHERE att.attacl IS NOT NULL AND c.oid IN ('public.perfiles'::regclass,'public.establecimientos'::regclass,'public.establecimientos_usuarios'::regclass,'public.bit56_validadores'::regclass,'public.usuarios_auditoria'::regclass) AND a.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated'))) s) = '7b69a42e062cb95d3fd63964c089d343' THEN 'OK' ELSE 'DERIVA (revisar antes de aplicar)' END
UNION ALL SELECT 'recuento perfiles/vinculos/validadores/atenciones/auditoria (base 3/7/1/6/0)', 'VER ' || (SELECT count(*) FROM public.perfiles)::text||'/'||(SELECT count(*) FROM public.establecimientos_usuarios)::text||'/'||(SELECT count(*) FROM public.bit56_validadores)::text||'/'||(SELECT count(*) FROM public.atenciones_clinicas)::text||'/'||(SELECT count(*) FROM public.usuarios_auditoria)::text;
